/**
 * Remote Asset Auto-Sync Service
 * Fetches visual assets generated by GitHub Actions and automatically
 * provisions Sanity coverImage, gallery, and previewGif.
 */

import { writeClient } from "@/lib/sanity/write-client";

export type SyncAssetsOptions = {
  owner: string;
  repo: string;
  token: string;
  branch?: string;
  projectId?: string;
};

export type SyncAssetsResult = {
  success: boolean;
  projectId: string;
  syncedAssets: string[];
  coverImageSet: boolean;
  previewGifSet: boolean;
  message: string;
};

/**
 * Fetches binary file buffer from GitHub via raw contents endpoint
 */
async function fetchGitHubAssetBuffer(
  owner: string,
  repo: string,
  filePath: string,
  branch: string,
  token: string
): Promise<{ buffer: Buffer; filename: string } | null> {
  try {
    // 1. Try raw content via GitHub API headers
    const rawRes = await fetch(
      `https://api.github.com/repos/${owner}/${repo}/contents/${filePath}?ref=${encodeURIComponent(branch)}`,
      {
        headers: {
          Authorization: `Bearer ${token}`,
          Accept: "application/vnd.github.v3.raw",
        },
      }
    );

    if (rawRes.ok) {
      const arrayBuffer = await rawRes.arrayBuffer();
      if (arrayBuffer.byteLength > 100) {
        return {
          buffer: Buffer.from(arrayBuffer),
          filename: filePath.split("/").pop() || "asset",
        };
      }
    }

    // 2. Fallback to standard contents API metadata (which provides download_url or base64)
    const jsonRes = await fetch(
      `https://api.github.com/repos/${owner}/${repo}/contents/${filePath}?ref=${encodeURIComponent(branch)}`,
      {
        headers: {
          Authorization: `Bearer ${token}`,
          Accept: "application/vnd.github+json",
        },
      }
    );

    if (!jsonRes.ok) return null;

    const data = await jsonRes.json();
    if (data.download_url) {
      const dlRes = await fetch(data.download_url);
      if (dlRes.ok) {
        const buf = await dlRes.arrayBuffer();
        return {
          buffer: Buffer.from(buf),
          filename: data.name || filePath.split("/").pop() || "asset",
        };
      }
    }

    if (data.content && data.encoding === "base64") {
      return {
        buffer: Buffer.from(data.content, "base64"),
        filename: data.name || filePath.split("/").pop() || "asset",
      };
    }
  } catch (err) {
    console.warn(`[Sync Assets] Warning fetching ${filePath}:`, err);
  }

  return null;
}

/**
 * Syncs generated repository visual assets (hero.png, fullpage.png, mobile.png, preview.gif)
 * directly into the project document's coverImage, gallery, and previewGif fields.
 */
export async function syncRepoAssetsToProject(
  options: SyncAssetsOptions
): Promise<SyncAssetsResult> {
  const { owner, repo, token, branch = "main", projectId: explicitProjectId } = options;
  const fullName = `${owner}/${repo}`;

  // 1. Resolve Sanity project document
  let targetProjectId = explicitProjectId;
  if (!targetProjectId) {
    const matching = await writeClient.fetch<{ _id: string; coverImage?: unknown; gallery?: unknown[] }[]>(
      `*[_type == "project" && (github match $pattern || github match $exact)]{ _id, coverImage, gallery }`,
      {
        pattern: `*${fullName}*`,
        exact: `*${repo}*`,
      }
    );

    if (matching && matching.length > 0) {
      // Prioritize draft if exists, otherwise published
      const draft = matching.find((p) => p._id.startsWith("drafts."));
      targetProjectId = draft ? draft._id : matching[0]._id;
    }
  }

  if (!targetProjectId) {
    throw new Error(`No matching Sanity project found for repository "${fullName}". Create or analyze the project first.`);
  }

  // 2. Fetch existing project to inspect current coverImage and gallery
  const existingProject = await writeClient.fetch<{
    _id: string;
    coverImage?: { asset?: { _ref: string } };
    gallery?: Array<{ _key?: string; caption?: string; asset?: { _ref: string } }>;
    previewGif?: { asset?: { _ref: string } };
  }>(
    `*[_id == $id][0]{ _id, coverImage, gallery, previewGif }`,
    { id: targetProjectId }
  );

  const syncedAssets: string[] = [];
  let coverImageRef: string | null = null;
  let previewGifRef: string | null = null;
  const newGalleryItems: Array<{
    _key: string;
    _type: string;
    caption: string;
    alt: string;
    asset: {
      _type: string;
      _ref: string;
    };
  }> = [];

  // 3. Define target assets to look for
  const targetFiles = [
    { path: "assets/hero.png", caption: "Desktop Hero View", isCoverCandidate: true },
    { path: "assets/fullpage.png", caption: "Fullpage Scrolling Architecture", isCoverCandidate: false },
    { path: "assets/mobile.png", caption: "Mobile Responsive Layout", isCoverCandidate: false },
  ];

  // 4. Download and upload screenshots to Sanity Asset pipeline
  for (const item of targetFiles) {
    const assetData = await fetchGitHubAssetBuffer(owner, repo, item.path, branch, token);
    if (assetData) {
      console.log(`[Sync Assets] Uploading ${item.path} (${assetData.buffer.length} bytes) to Sanity...`);
      const sanityAsset = await writeClient.assets.upload("image", assetData.buffer, {
        filename: assetData.filename,
      });

      if (sanityAsset && sanityAsset._id) {
        syncedAssets.push(item.path);

        // Keep reference for coverImage
        if (item.isCoverCandidate && !existingProject?.coverImage?.asset?._ref) {
          coverImageRef = sanityAsset._id;
        }

        newGalleryItems.push({
          _key: `sync_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`,
          _type: "galleryImage",
          caption: item.caption,
          alt: `${repo} ${item.caption}`,
          asset: {
            _type: "reference",
            _ref: sanityAsset._id,
          },
        });
      }
    }
  }

  // 5. Look for animated preview GIF
  const gifCandidates = ["assets/preview.gif", "assets/preview-desktop.gif", "assets/mobile.gif"];
  for (const gifPath of gifCandidates) {
    const gifData = await fetchGitHubAssetBuffer(owner, repo, gifPath, branch, token);
    if (gifData) {
      console.log(`[Sync Assets] Uploading ${gifPath} to Sanity...`);
      const sanityGif = await writeClient.assets.upload("image", gifData.buffer, {
        filename: gifData.filename,
      });
      if (sanityGif && sanityGif._id) {
        previewGifRef = sanityGif._id;
        syncedAssets.push(gifPath);
        break;
      }
    }
  }

  // 6. Patch Sanity project document
  const patch = writeClient.patch(targetProjectId);
  let coverImageSet = false;
  let previewGifSet = false;

  // Set coverImage if we found one and project has no cover yet
  if (coverImageRef) {
    patch.set({
      coverImage: {
        _type: "image",
        alt: `${repo} Cover Preview`,
        asset: {
          _type: "reference",
          _ref: coverImageRef,
        },
      },
    });
    coverImageSet = true;
  } else if (!existingProject?.coverImage && newGalleryItems.length > 0) {
    // Fallback cover image to first gallery item
    patch.set({
      coverImage: {
        _type: "image",
        alt: `${repo} Cover Preview`,
        asset: {
          _type: "reference",
          _ref: newGalleryItems[0].asset._ref,
        },
      },
    });
    coverImageSet = true;
  }

  // Update or append to gallery
  if (newGalleryItems.length > 0) {
    const existingGallery = existingProject?.gallery || [];
    // Filter out existing items that already have the same caption
    const filteredExisting = existingGallery.filter(
      (eg) => !newGalleryItems.some((ng) => ng.caption === eg.caption)
    );
    patch.set({
      gallery: [...filteredExisting, ...newGalleryItems],
    });
  }

  // Set previewGif if found
  if (previewGifRef) {
    patch.set({
      previewGif: {
        _type: "image",
        asset: {
          _type: "reference",
          _ref: previewGifRef,
        },
      },
    });
    previewGifSet = true;
  }

  await patch.commit();
  console.log(`[Sync Assets] Successfully committed assets to project ${targetProjectId}!`);

  return {
    success: true,
    projectId: targetProjectId,
    syncedAssets,
    coverImageSet,
    previewGifSet,
    message: syncedAssets.length > 0
      ? `Successfully synced ${syncedAssets.length} visual assets (gallery, cover & animated GIF) to Sanity!`
      : "No new visual assets found in repository assets/ directory. Run visual capture first.",
  };
}
